from __future__ import annotations

import os
import threading
import time
from typing import Any

import httpx

from freesolo.utils.openai import require_positive_max_tokens

JUDGE_BASE_URL = "https://openrouter.ai/api/v1"
JUDGE_MODEL = "openai/gpt-oss-120b"
JUDGE_MODEL_ENV = "FREESOLO_JUDGE_MODEL"

_RETRYABLE_STATUS_CODES = frozenset({408, 409, 429, 500, 502, 503, 504})

_client_lock = threading.Lock()
_shared_client: httpx.Client | None = None


def resolve_judge_model(model: str | None = None) -> str:
    """Resolve the judge model: explicit argument, then env override, then default."""
    for candidate in (model, os.getenv(JUDGE_MODEL_ENV)):
        if isinstance(candidate, str) and candidate.strip():
            return candidate.strip()
    return JUDGE_MODEL


def _judge_client() -> httpx.Client:
    """Shared judge HTTP client.

    Reward scoring issues one judge call per rollout, so a fresh connection per
    call dominates latency; a pooled client amortizes TLS/TCP setup across the
    whole training run. Per-request timeouts are passed at call time.
    """
    global _shared_client
    with _client_lock:
        if _shared_client is None or _shared_client.is_closed:
            _shared_client = httpx.Client(
                timeout=60.0,
                limits=httpx.Limits(
                    max_connections=32,
                    max_keepalive_connections=16,
                ),
            )
        return _shared_client


def require_judge_api_key(api_key: str | None = None) -> str:
    resolved = api_key or os.getenv("OPENROUTER_API_KEY")
    if not resolved or not resolved.strip():
        raise RuntimeError("OPENROUTER_API_KEY is required")
    return resolved.strip()


def judge_headers(
    *,
    api_key: str | None = None,
    referer: str | None = None,
    title: str | None = None,
) -> dict[str, str]:
    headers = {
        "Authorization": f"Bearer {require_judge_api_key(api_key)}",
        "Content-Type": "application/json",
    }
    if referer:
        headers["HTTP-Referer"] = referer
    if title:
        headers["X-Title"] = title
    return headers


def build_judge_payload(
    *,
    messages: list[dict[str, str]],
    max_tokens: int,
    temperature: float | None = None,
    response_format: dict[str, Any] | None = None,
    extra_body: dict[str, Any] | None = None,
    model: str | None = None,
) -> dict[str, Any]:
    resolved_model = resolve_judge_model(model)
    if extra_body and "model" in extra_body:
        raise ValueError(
            "Pass the judge model via the model argument or the "
            f"{JUDGE_MODEL_ENV} environment variable, not extra_body"
        )
    payload: dict[str, Any] = {
        "model": resolved_model,
        "messages": messages,
        "max_tokens": require_positive_max_tokens(max_tokens),
    }
    if temperature is not None:
        payload["temperature"] = temperature
    if response_format is not None:
        payload["response_format"] = response_format
    if extra_body:
        payload.update(extra_body)
    return payload


def _is_retryable_error(error: Exception) -> bool:
    if isinstance(error, httpx.HTTPStatusError):
        return error.response.status_code in _RETRYABLE_STATUS_CODES
    return isinstance(error, (httpx.TimeoutException, httpx.TransportError))


def judge_chat_completion(
    *,
    messages: list[dict[str, str]],
    max_tokens: int,
    api_key: str | None = None,
    base_url: str = JUDGE_BASE_URL,
    timeout_seconds: float = 60.0,
    temperature: float | None = None,
    response_format: dict[str, Any] | None = None,
    referer: str | None = None,
    title: str | None = None,
    extra_body: dict[str, Any] | None = None,
    model: str | None = None,
    max_retries: int = 3,
    retry_backoff_seconds: float = 1.0,
) -> dict[str, Any]:
    payload = build_judge_payload(
        messages=messages,
        max_tokens=max_tokens,
        temperature=temperature,
        response_format=response_format,
        extra_body=extra_body,
        model=model,
    )
    headers = judge_headers(api_key=api_key, referer=referer, title=title)
    url = f"{base_url.rstrip('/')}/chat/completions"

    total_attempts = max(0, int(max_retries)) + 1
    last_error: Exception | None = None
    for attempt in range(total_attempts):
        if attempt > 0:
            time.sleep(retry_backoff_seconds * (2 ** (attempt - 1)))
        try:
            response = _judge_client().post(
                url,
                headers=headers,
                json=payload,
                timeout=timeout_seconds,
            )
            response.raise_for_status()
            data = response.json()
        except Exception as error:
            if not _is_retryable_error(error):
                raise
            last_error = error
            continue
        if not isinstance(data, dict):
            raise RuntimeError("Judge response must be a JSON object")
        return data

    raise RuntimeError(
        f"Judge request failed after {total_attempts} attempts"
    ) from last_error


def generate_judge_text(
    *,
    messages: list[dict[str, str]],
    max_tokens: int,
    api_key: str | None = None,
    base_url: str = JUDGE_BASE_URL,
    timeout_seconds: float = 60.0,
    temperature: float | None = None,
    response_format: dict[str, Any] | None = None,
    referer: str | None = None,
    title: str | None = None,
    extra_body: dict[str, Any] | None = None,
    model: str | None = None,
    max_retries: int = 3,
    retry_backoff_seconds: float = 1.0,
) -> str:
    response = judge_chat_completion(
        messages=messages,
        max_tokens=max_tokens,
        api_key=api_key,
        base_url=base_url,
        timeout_seconds=timeout_seconds,
        temperature=temperature,
        response_format=response_format,
        referer=referer,
        title=title,
        extra_body=extra_body,
        model=model,
        max_retries=max_retries,
        retry_backoff_seconds=retry_backoff_seconds,
    )
    return extract_judge_message_content(response)


def extract_judge_message_content(payload: dict[str, Any]) -> str:
    choices = payload.get("choices")
    if not isinstance(choices, list) or not choices:
        raise RuntimeError("Judge response did not contain choices")
    first_choice = choices[0]
    message = first_choice.get("message") if isinstance(first_choice, dict) else None
    content = message.get("content") if isinstance(message, dict) else None
    if not isinstance(content, str) or not content.strip():
        raise RuntimeError("Judge response did not contain content")
    return content.strip()
